create table device_repo (
 external_id VARCHAR(100) not null UNIQUE,
 manufacturer_id int,
 original_manuf_id int,
 resolution_width int,
 resolution_height int,
 density DOUBLE,
 manufacturer_name VARCHAR(100),
 model_name VARCHAR(100),
 display_marketing_name VARCHAR(100),
 device_os_id int,
 is_wireless_device VARCHAR(100),
 is_rta_handset VARCHAR(100),
 is_tablet VARCHAR(100),
 is_smart_phone VARCHAR(100),
 model_id int,
 os_version_id int,
 device_type_id int,
 os_major_version VARCHAR(100),
 os_version VARCHAR(100)
);

